#include "Restoration.h"
static double restoredTone(const AudioBuffer<float>& audio,int channel,double hz,double rate,int first,int end){double sine=0,cosine=0;for(int i=first;i<end;++i){double phase=2*MathConstants<double>::pi*hz*i/rate;sine+=audio.getSample(channel,i)*std::sin(phase);cosine+=audio.getSample(channel,i)*std::cos(phase);}return 2*std::sqrt(sine*sine+cosine*cosine)/(end-first);}
static bool sameRestorationAudio(const AudioBuffer<float>& a,const AudioBuffer<float>& b){if(a.getNumChannels()!=b.getNumChannels()||a.getNumSamples()!=b.getNumSamples())return false;for(int c=0;c<a.getNumChannels();++c)for(int i=0;i<a.getNumSamples();++i)if(a.getSample(c,i)!=b.getSample(c,i))return false;return true;}
static void testRestoration(const File& root){
    RestorationOptions options;RestorationStats stats;AudioBuffer<float> out;
    for(int rate:{8000,44100,48000,96000,192000}){
        AudioBuffer<float> source(2,rate);for(int i=0;i<rate;++i){source.setSample(0,i,(float)(.2+.1*std::sin(2*MathConstants<double>::pi*400*i/rate)));source.setSample(1,i,(float)(-.3+.08*std::sin(2*MathConstants<double>::pi*700*i/rate)));}
        expect(restoreWave(source,rate,0,rate,options,out,stats).wasOk()&&out.getNumSamples()==rate&&std::abs(stats.dcAfter[0])<1e-7&&std::abs(stats.dcAfter[1])<1e-7,"DC restoration removes independent channel offsets at every supported rate family");expect(std::abs(restoredTone(out,0,400,rate,0,rate)-.1)<1e-6&&std::abs(restoredTone(out,1,700,rate,0,rate)-.08)<1e-6,"DC removal retains musical tone amplitudes and stereo separation");
        int first=rate/4,end=3*rate/4;expect(restoreWave(source,rate,first,end,options,out,stats).wasOk(),"selected DC restoration succeeds");bool unchanged=true;for(int c=0;c<2;++c)for(int i=0;i<rate;++i)if(i<first||i>=end||i==first||i==end-1)unchanged&=source.getSample(c,i)==out.getSample(c,i);expect(unchanged,"audio outside selection and its blended endpoint samples stay bit-exact");
        options.strength=0;expect(restoreWave(source,rate,first,end,options,out,stats).wasOk()&&sameRestorationAudio(source,out)&&stats.changed==std::array<uint64_t,2>{},"zero-strength restoration is an exact no-op");options.strength=1;
    }
    for(double mains:{50.,60.}){
        int rate=48000,count=rate*3;AudioBuffer<float> source(2,count);for(int i=0;i<count;++i){double t=i/(double)rate;source.setSample(0,i,(float)(.2*std::sin(2*MathConstants<double>::pi*mains*t)+.1*std::sin(2*MathConstants<double>::pi*mains*2*t)+.15*std::sin(2*MathConstants<double>::pi*1000*t)));source.setSample(1,i,(float)(.1*std::sin(2*MathConstants<double>::pi*1600*t)));}options.kind=RestorationKind::hum;options.humHz=mains;options.harmonics=2;
        expect(restoreWave(source,rate,0,count,options,out,stats).wasOk(),"two-pass mains/harmonic restoration succeeds for 50 and 60 Hz");double fundamental=restoredTone(out,0,mains,rate,rate,rate*2),second=restoredTone(out,0,mains*2,rate,rate,rate*2);expect(fundamental<.002&&second<.001,"stationary mains fundamental and configured harmonic attenuate by at least 40 dB away from edges");expect(std::abs(restoredTone(out,0,1000,rate,rate,rate*2)-.15)<.001&&std::abs(restoredTone(out,1,1600,rate,rate,rate*2)-.1)<.001,"hum filters retain distant musical frequencies and channel identity");
    }
    AudioBuffer<float> clicks(2,4096);for(int i=0;i<4096;++i){clicks.setSample(0,i,.1f);clicks.setSample(1,i,-.2f);}clicks.setSample(0,1000,.9f);for(int i=1200;i<1203;++i)clicks.setSample(0,i,-.8f);for(int i=2000;i<2009;++i)clicks.setSample(0,i,.9f);clicks.setSample(0,3,.9f);options.kind=RestorationKind::clicks;options.clickWidth=3;
    expect(restoreWave(clicks,48000,0,4096,options,out,stats).wasOk()&&stats.clicks[0]==2&&stats.clicks[1]==0&&stats.changed[0]==4,"isolated one/three-sample clicks repair as distinct bounded runs");bool repaired=out.getSample(0,1000)==.1f;for(int i=1200;i<1203;++i)repaired&=out.getSample(0,i)==.1f;for(int i=2000;i<2009;++i)repaired&=out.getSample(0,i)==.9f;expect(repaired&&out.getSample(0,3)==.9f,"linear click repair preserves longer events and avoids guessing the first/last sixteen frames");bool rightExact=true;for(int i=0;i<4096;++i)rightExact&=out.getSample(1,i)==clicks.getSample(1,i);expect(rightExact,"click restoration never changes an unflagged opposite channel");
    options.strength=.5;expect(restoreWave(clicks,48000,0,4096,options,out,stats).wasOk()&&std::abs(out.getSample(0,1000)-.5)<1e-6,"click strength provides a genuine dry/wet interpolation");
    AudioBuffer<float> sentinel(2,1);sentinel.clear();sentinel.setSample(0,0,.123f);out.makeCopyOf(sentinel);stats.changed[0]=123;std::atomic<bool> cancel{true};expect(restoreWave(clicks,48000,0,4096,options,out,stats,&cancel).failed()&&sameRestorationAudio(out,sentinel)&&stats.changed[0]==123,"cancellation preserves caller output and statistics atomically");
    for(int test=0;test<7;++test){auto invalid=options;if(test==0)invalid.kind=(RestorationKind)4;if(test==1)invalid.q=0;if(test==2)invalid.strength=1.1;if(test==3)invalid.clickThreshold=std::numeric_limits<double>::quiet_NaN();if(test==4)invalid.harmonics=7;if(test==5)invalid.humHz=55;if(test==6)invalid.clickWidth=9;expect(restoreWave(clicks,48000,0,4096,invalid,out,stats).failed()&&sameRestorationAudio(out,sentinel),"invalid restoration settings reject without replacing output");}
    options.kind=RestorationKind::hum;expect(restoreWave(clicks,48000,0,4096,options,out,stats).failed()&&sameRestorationAudio(out,sentinel),"short hum selections reject instead of inventing filter context");options.kind=RestorationKind::dc;expect(restoreWave(clicks,48000,-1,4096,options,out,stats).failed()&&restoreWave(clicks,48000,0,4097,options,out,stats).failed(),"invalid half-open restoration ranges reject");auto bad=clicks;bad.setSample(0,50,std::numeric_limits<float>::infinity());expect(restoreWave(bad,48000,0,4096,options,out,stats).failed(),"non-finite source audio cannot reach restoration output");
    auto settings=root.getChildFile("restoration-settings.json");expect(saveRestorationOptions(settings,options).wasOk(),"restoration preferences save atomically outside projects");RestorationOptions loaded;expect(loadRestorationOptions(settings,loaded).wasOk()&&loaded==options,"all restoration modes and numerical settings round-trip");auto previous=settings.loadFileAsString();auto invalid=options;invalid.q=100;expect(saveRestorationOptions(settings,invalid).failed()&&settings.loadFileAsString()==previous,"invalid preferences retain the previous file");auto json=restorationToJson(options);json.getDynamicObject()->setProperty("harmonics",1e100);expect(restorationFromJson(json,loaded).failed()&&loaded==options,"huge integer-like JSON cannot overflow restoration counts");json=restorationToJson(options);json.getDynamicObject()->setProperty("strength","1");expect(restorationFromJson(json,loaded).failed(),"preferences require numeric values rather than coercing strings");
    Assets assets;auto silentProject=emptyProject();auto engine=makeEngine(silentProject,assets,root);engine->stop();Sample loud;loud.sampleRate=48000;loud.audio.setSize(2,4800);for(int i=0;i<4800;++i){loud.audio.setSample(0,i,2);loud.audio.setSample(1,i,-1.5f);}AudioBuffer<float> preview(2,512);
    expect(engine->preview(&loud,0,.1,.2f),"preview accepts an explicit shared attenuation for paired restoration audio");engine->render(preview.getWritePointer(0),preview.getWritePointer(1),512);expect(std::abs(preview.getSample(0,0)-.4f)<1e-7&&std::abs(preview.getSample(1,0)+.3f)<1e-7,"preview gain is applied equally without clipping loud float source data");expect(!engine->preview(&loud,0,.1,0)&&!engine->preview(&loud,0,.1,2)&&!engine->preview(&loud,0,.1,std::numeric_limits<float>::quiet_NaN()),"invalid audition gain cannot enter the audio-thread queue");engine->stop();engine->preview(&loud);engine->render(preview.getWritePointer(0),preview.getWritePointer(1),512);expect(preview.getSample(0,0)==1&&preview.getSample(1,0)==-1,"default Browser preview retains its historical gain and limiter behavior");engine->stop();
    expect(restorationSummary(stats,options,48000,0,4096).contains("No normalization")&&restorationName(RestorationKind::clicks).contains("clicks"),"native restoration review declares measured units and practical processing limits");
}
